+      box-shadow: 0 0 0 0.25rem rgba(124, 58, 237, 0.25);
+    }
+
+    input[aria-invalid="true"] {
+      border-color: var(--error);
+      box-shadow: 0 0 0 0.2rem rgba(251, 113, 133, 0.14);
