+      box-shadow: 0 1rem 2rem rgba(79, 70, 229, 0.28);
+      transition: transform 160ms ease, box-shadow 160ms ease, filter 160ms ease;
+    }
+
+    button:hover {
+      filter: brightness(1.08);
+      box-shadow: 0 1.2rem 2.4rem rgba(79, 70, 229, 0.36);
+      transform: translateY(-1px);
+    }
+
+    button:focus-visible {
+      outline: 0.2rem solid var(--accent-light);
+      outline-offset: 0.25rem;
+    }
+
+    button:active {
+      transform: translateY(0);
+    }
+
+    .success-message {
+      margin: 1rem 0 0;
+      color: #86efac;
+      font-weight: 700;
+      line-height: 1.5;
+    }
+  </style>
+</head>
+<body>
+  <main>
+    <section class="support-card" aria-labelledby="support-title">
+      <h1 id="support-title">Contact support</h1>
+      <p class="intro">Send us your details and our support team will get back to you as soon as possible.</p>
+
+      <form id="support-form" novalidate>
+        <div class="form-field">
+          <label for="full-name">Full name</label>
+          <input
+            type="text"
+            id="full-name"
+            name="fullName"
+            autocomplete="name"
+            placeholder="Jane Doe"
+            required
+            aria-describedby="full-name-error"
+          >
+          <p class="error-message" id="full-name-error" aria-live="polite"></p>
+        </div>
+
+        <div class="form-field">
+          <label for="email">Email address</label>
+          <input
+            type="email"
+            id="email"
+            name="email"
+            autocomplete="email"
+            placeholder="jane@example.com"
+            required
+            aria-describedby="email-error"
+          >
+          <p class="error-message" id="email-error" aria-live="polite"></p>
+        </div>
+
+        <div class="form-field">
+          <label for="phone">Phone number <span aria-hidden="true">(optional)</span></label>
+          <input
+            type="tel"
+            id="phone"
+            name="phone"
+            autocomplete="tel"
+            placeholder="+1 555 123 4567"
+            aria-describedby="phone-help phone-error"
+          >
+          <p class="helper-text" id="phone-help">Expected format: include digits, spaces, dashes, parentheses, or an optional leading plus sign.</p>
+          <p class="error-message" id="phone-error" aria-live="polite"></p>
+        </div>
+
+        <button type="submit">Submit request</button>
+        <p class="success-message" id="success-message" aria-live="polite"></p>
+      </form>
+    </section>
+  </main>
+
+  <script>
+    const form = document.querySelector("#support-form");
+    const successMessage = document.querySelector("#success-message");
+
+    const fields = {
+      fullName: {
+        input: document.querySelector("#full-name"),
+        error: document.querySelector("#full-name-error"),
+        validate(value) {
+          return value.trim() ? "" : "Full name is required.";
+        }
+      },
+      email: {
+        input: document.querySelector("#email"),
+        error: document.querySelector("#email-error"),
+        validate(value) {
+          const trimmedValue = value.trim();
+          const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
+
+          if (!trimmedValue) {
+            return "Email address is required.";
+          }
+
+          return emailPattern.test(trimmedValue) ? "" : "Enter a valid email address.";
+        }
+      },
+      phone: {
+        input: document.querySelector("#phone"),
+        error: document.querySelector("#phone-error"),
+        validate(value) {
+          const trimmedValue = value.trim();
+          const phonePattern = /^\+?[0-9\s().-]{7,20}$/;
+
+          if (!trimmedValue) {
+            return "";
+          }
+
+          return phonePattern.test(trimmedValue)
+            ? ""
+            : "Enter a valid phone number using digits, spaces, dashes, parentheses, or a leading plus sign.";
+        }
+      }
+    };
+
+    function setFieldError(field, message) {
+      field.error.textContent = message;
+      field.input.setAttribute("aria-invalid", message ? "true" : "false");
+    }
+
+    function validateField(field) {
+      const message = field.validate(field.input.value);
+      setFieldError(field, message);
+      return !message;
+    }
+
+    Object.values(fields).forEach((field) => {
+      field.input.addEventListener("input", () => {
+        validateField(field);
+        successMessage.textContent = "";
+      });
+    });
+
+    form.addEventListener("submit", (event) => {
+      event.preventDefault();
+
+      const isValid = Object.values(fields).every(validateField);
+      successMessage.textContent = "";
+
+      if (!isValid) {
+        const firstInvalidField = Object.values(fields).find((field) => field.input.getAttribute("aria-invalid") === "true");
+        firstInvalidField.input.focus();
+        return;
+      }
+
+      form.reset();
+      Object.values(fields).forEach((field) => setFieldError(field, ""));
+      successMessage.textContent = "Thanks. Your support request is ready to be sent.";
+    });
+  </script>
+</body>
+</html>
*** End Patch
